    """Evaluate reverse Polish notation over floats."""
    stack = []
    for token in tokens:
        if token in {"+", "-", "*", "/"}:
            a = stack.pop()
            b = stack.pop()
            if token == "+":
                stack.append(b + a)
            elif token == "-":
                stack.append(b - a)
            elif token == "*":
                stack.append(b * a)
            else:
                stack.append(b / a)
        else:
            stack.append(float(token))
    return stack[-1]

